  ('t3_36296', 'Conquest am Teutoburger Wald #1, World Event', '2025-03-15', '2025-03-15', 16, 'Deutschland', 'Bielefeld', 33609, 'Rabenhof 76', 'Erstes Conquest Turnier in Bielefeld. 2k Punkte. Word Event.', 'https://www.tabletopturniere.de/t3_tournament.php?tid=36296', '3e8e29e7634848bf7226f98ef33effac04efabbd48c1b99eacc6e3eddfeaa522', 'ended', 3, 'ended', '2025-03-15 00:00:00'),
  ('t3_37534', 'Conquest im Zwergenfürst - Season 2', '2025-03-22', '2025-03-22', 10, 'Deutschland', 'Hamburg', 22041, 'Wandsbeker Allee 72', 'Um 11:15 geht es los, das erste 2025er Turnier im Zwergenfürst! Tickets hier erhältlich, eine Anmeldung auf T3 ist nur dann gültig, wenn ein Ticket auf den Usernamen gekauft wurde. https://www.zwergenfuerst.de/conquest-turnier?slotId=2e906ae299fb4ee38b4f9', 'https://www.tabletopturniere.de/t3_tournament.php?tid=37534', '3ebcabe7d4ec3aba17522f26b3d85d444a7cec3af9627583f91fb2001ff9815e', 'ended', 3, 'ended', '2025-03-22 00:00:00'),
  ('t3_38398', 'Conquest of Asgard', '2025-09-20', '2025-09-20', 20, 'Deutschland', 'Aschaffenburg', 63741, 'Großostheimer Straße 189', 'Erstes Aschaffenburger Conquest Turnier, Worlds Turnier, 3 Spiele, 2000 Punkte', 'https://www.tabletopturniere.de/t3_tournament.php?tid=38398', '329b13940b0c3aef4a288f85a70f4d1178391f687d7008f184fcc0992ff987a2', 'ended', 3, 'ended', '2025-09-20 00:00:00'),
  ('t3_38050', 'Conquest am Teutoburger Wald #2, World Event', '2025-10-04', '2025-10-04', 16, 'Deutschland', 'Bielefeld', 33609, 'Rabenhof 76', 'Das zweite 2000 Punkte Turnier in Bielefeld. Second 2000 points tournament in Bielefeld.', 'https://www.tabletopturniere.de/t3_tournament.php?tid=38050', '4ebe49c1880bb5155bd776ca0052487c30073978f1818429e8577d7b1b283a63', 'ended', 3, 'ended', '2025-10-04 00:00:00'),
  ('t3_38016', 'Conquering from the Fjords to the Alps', '2025-11-08', '2025-11-09', 64, 'Deutschland', 'Duisburg', 47229, 'Am Borgschenhof 8', 'Drunken Dwarfs present: We invite you to the first inoffical Regional Championship at the Zwergenbunker! There will be 5 rounds played with a 2000-point list. Wir laden euch zur 1. Inoffiziellen Regional Championship im Zwergenbunker ein! Es werden 5 Rund', 'https://www.tabletopturniere.de/t3_tournament.php?tid=38016', 'b17a9fd812365db7c414190f933d3f216062048ab1679e28992af8d26e22d629', 'ended', 5, 'ended', '2025-11-08 00:00:00'),
  ('t3_40110', 'Der Ruf des Kraken - Vol. 2', '2026-02-07', '2026-02-07', 20, 'Deutschland', 'Hamburg', 21029, 'Wentorfer Straße 26', 'Es werden 2000 Punkte gespielt in drei Runden ohne Bemalpflicht. Wir öffnen die Türen um 9:30 und starten um 10.00 mit der ersten Runde. Startgebühr bitte an per Paypal (Freunde) an chris.conquest@posteo.de mit eurem T3 Namen + Turniername.', 'https://www.tabletopturniere.de/t3_tournament.php?tid=40110', '99ccdd331609e77e5f0628f01b2431a9dc1bb65afa85533e8d3a932989718d64', 'ended', 3, 'ended', '2026-02-07 00:00:00'),
  ('t3_39299', 'Conquest of Asgard 3', '2026-03-28', '2026-03-28', 20, 'Deutschland', 'Aschaffenburg', 63741, 'Großostheimer Straße 189', 'weitere Infos folgen', 'https://www.tabletopturniere.de/t3_tournament.php?tid=39299', 'a9fb7ff4b71135c0b68f3fcd99188fb165a4654e3864079c82f08644b38655cb', 'ended', 3, 'ended', '2026-03-28 00:00:00'),
