INSERT INTO `tournaments` (`id`,`name`,`date`,`end_date`,`max_players`,`country`,`city`,`zip`,`address`,`description`,`external_link`,`orga_id`,`state`,`current_round`,`current_round_state`,`created_at`) VALUES
  ('t3_35590', 'III. Conquest im Zwergenfürst', '2024-06-22', '2024-06-22', 10, 'Deutschland', 'Hamburg', 22041, 'Wandsbeker Allee 72', 'Format: 1500 Punkte / 3 Spiele Mindestbemalstandard: Battle Ready', 'https://www.tabletopturniere.de/t3_tournament.php?tid=35590', '7b0a257767d2710b22dc6e5215d3273410df0366b0279fd1dd9bfd9d46cded21', 'ended', 3, 'ended', '2024-06-22 00:00:00'),
  ('t3_35453', 'King Kong-Quest - Big Banana Bambule', '2024-06-23', '2024-06-23', 16, 'Deutschland', 'Dresden', 1069, 'Hinterhof über der Treppe, Ferdinandstraße 12', 'Ganz nach dem Motto "Make Ostzone great again" lädt die Dresdner Conquest Community euch ganz herzlich zum ersten Turnier ein. 1500P, 3 Spiele. Spieler*Innen die mehr als 1500P besitzen dürfen auch gerne eine zweite Liste mit 2000P mitbringen und dann vor', 'https://www.tabletopturniere.de/t3_tournament.php?tid=35453', '1c3107f2077870bf5e6123701559b2cd617ef678061258aca5fdd01b895bb5bf', 'ended', 3, 'ended', '2024-06-23 00:00:00'),
  ('t3_36546', 'Drachenfeuer @Conquest - Last Argument of Kingz 05', '2024-11-16', '2024-11-16', 8, 'Deutschland', 'Augsburg', 86150, 'Vorderer Lech 43', 'Heyho, wir machen diese Jahr ein Ladenturnier mit 2000 Pkt. auf! Sowohl die Listen bitte ausgedruckt mitbringen und einen PB Pin besitzen. Missionen und nähere Details sind unter "Regeln" bekannt gegeben. Ihr könnt gerne die Gebühr via PayPal Freunde bei ', 'https://www.tabletopturniere.de/t3_tournament.php?tid=36546', '19f744c4609029c8efdf386c76383c0261e4e48b30b03cf2c4bcd05ab1aef9ba', 'ended', 3, 'ended', '2024-11-16 00:00:00'),
  ('t3_38340', 'Drachenfeuer @Conquest - Last Argument of Kingz 06', '2025-06-14', '2025-06-14', 8, 'Deutschland', 'Augsburg', 86150, 'Vorderer Lech 43', 'Hallo zusammen, wir machen unser nächstes Ladenturnier mit 2000 Pkt! Sowohl die Listen bitte ausgedruckt mitbringen und einen PB Pin besitzen. Missionen und nähere Details sind unter "Regeln" bekannt gegeben. Ihr könnt gerne die Gebühr via PayPal Freunde ', 'https://www.tabletopturniere.de/t3_tournament.php?tid=38340', 'e8a5942e7e99dea17423866540bca23a1212fe93eb3c94fe873d4533576fb6e5', 'ended', 3, 'ended', '2025-06-14 00:00:00'),
  ('t3_38455', 'Der Ruf des Kraken Vol. 1', '2025-07-05', '2025-07-05', 18, 'Deutschland', 'Hamburg', 21029, 'Wentorfer Str. 26', 'Wir veranstalten unser erstes Conquest Last Argument of Kings Turnier bei den Tabletop Freibeutern. Es werden 2000 Punkte gespielt in drei Runden ohne Bemalpflicht. Wir öffnen die Türen um 9:30 und starten um 10.00 mit der ersten Runde. Startgebühr bitte ', 'https://www.tabletopturniere.de/t3_tournament.php?tid=38455', 'a1b85fcd904530f0b43a654c334536da265c8d500fe03cdc81db1161e1986754', 'ended', 3, 'ended', '2025-07-05 00:00:00'),
  ('t3_38614', 'Krawall im Stall - Conquest Turnier I', '2025-07-05', '2025-07-05', 6, 'Deutschland', 'Telgte', 48291, 'siehe Koordinaten', 'Unser erstes Conquest-Turnier in unseren Clubräumen. Wir spielen 3 Runden a 2000 Punkte', 'https://www.tabletopturniere.de/t3_tournament.php?tid=38614', '77f84c4271d066595c86451134ac7c14ecb270c014233717a734a9697510cf8c', 'ended', 3, 'ended', '2025-07-05 00:00:00'),
  ('t3_39839', 'Ein Conquest Turnier wo? - In Lindenstruth! Invitational Origins', '2026-02-28', '2026-02-28', 16, 'Deutschland', 'Reiskirchen', 35447, 'Am Heegersgraben', 'Eine Art regionales Turnier, welches mehr dem Spaß und der Freude am Hobby und nettem Austausch dienen soll und weniger einem kompetitiven Powerplay.', 'https://www.tabletopturniere.de/t3_tournament.php?tid=39839', '21e17f5b207d2e30426ba408f1ef843db736b083c1aa9990da00ca90f1189eb1', 'ended', 3, 'ended', '2026-02-28 00:00:00'),
  ('t3_38773', 'Last Argument of Ländle II', '2026-04-18', '2026-04-19', 26, 'Deutschland', 'Winnenden', 71364, 'Albertviller Str. 50', 'Gespielt werden 5 Runden an 2 Tagen mit 2000 Punkte nach dem aktuellen Regelwerk. Es gibt offiziellen Preissupport von Para Bellum und vor allem viel Spaß und gute Laune an den Tagen.', 'https://www.tabletopturniere.de/t3_tournament.php?tid=38773', '3147f882ddab52220ef2411839f087709a399747959ff47442366be7bd338569', 'ended', 5, 'ended', '2026-04-18 00:00:00');
