  ('t3_35341', 'Legions of EÄ - Last Argument of Kingz 01', '2024-06-29', '2024-06-29', 12, 'Deutschland', 'Augsburg', 86199, 'Wellenburg 11', '1500 Pkt Conquest - Last Argument of Kingz Turnier im neuen Club House der Legio Intermeratus Missionen: #4 Echolon, #8 Bulwark und #7 Melee Stand 29.04.24 Weitere Informationen entnimmt bitte aus der Regel-Sektion :) Es gibt nur 6 Parkplätze vor dem Club', 'https://www.tabletopturniere.de/t3_tournament.php?tid=35341', '3951bcb018226e6bb55a7a9ea015846db1c08700fcd300fadea2c55b65b83fc1', 'ended', 3, 'ended', '2024-06-29 00:00:00'),
  ('t3_35895', 'Northern Bonelem Invitational Cup', '2024-08-10', '2024-08-11', 8, 'Deutschland', 'Ganderkesee', 27777, 'LA CASA DI NINO 1', 'Zwei Tage epische Conquest-Spiele im Jeder-gegen-Jeden-Modus mit Grillen, Karaoke und einem verwirrten Nick erwarten euch. Die Kosten werden geteilt und einige epische Bonelem-Pokale winken den drei Bestplatzierten. Wo? Ganderkesee Wann? 10. & 11. August ', 'https://www.tabletopturniere.de/t3_tournament.php?tid=35895', '925071c2fcc3e3f7cdadb5ce46732441f45ea5ad81008af6747e5904bd7ece17', 'ended', 5, 'ended', '2024-08-10 00:00:00'),
  ('t3_36740', 'Letztes Conquest Turnier im Zwergenfürst für 2024', '2024-11-30', '2024-11-30', 10, 'Deutschland', 'Hmburg', 22041, 'Wandsbeker Allee 72', 'Start ist 11:15 Gespielt werden: Melee Maelstrom Grind them Down Alles nach Swiss System in Kombination mit der PB App', 'https://www.tabletopturniere.de/t3_tournament.php?tid=36740', '3e2009314fc315948e15a3747bf4811added6d3d611b803d18371de44063bcc1', 'ended', 3, 'ended', '2024-11-30 00:00:00'),
  ('t3_34371', 'Sidequest - Conquest im Sidequest #4', '2024-12-07', '2024-12-07', 16, 'Deutschland', 'Bremerhaven', 27568, 'Am Gitter 1', 'Wir freuen uns auf einen gemeinsamen Tag mit tollen Conquest-Partien mit euch! Neulinge wie Erfahrene sind Willkommen!', 'https://www.tabletopturniere.de/t3_tournament.php?tid=34371', '9a40ada27a4eaa2b2988cdc5ee28a0d531839a25ff64a6d81f09bf86cf55aca7', 'ended', 3, 'ended', '2024-12-07 00:00:00'),
  ('t3_36657', 'Last Argument of the Ländle', '2025-04-05', '2025-04-06', 24, 'Deutschland', 'Winnenden', 71364, 'Albertvillerstraße 50', 'Das erste Conquest LAoK Turnier des Snake-Eyes e.V. Gespielt werden 5 Runden an 2 Tagen mit 2000 Punkte nach dem aktuellen Regelwerk. Es gibt offiziellen Preissupport von Para Bellum und vor allem viel Spaß und gute Laune an den Tagen.', 'https://www.tabletopturniere.de/t3_tournament.php?tid=36657', '3147f882ddab52220ef2411839f087709a399747959ff47442366be7bd338569', 'ended', 5, 'ended', '2025-04-05 00:00:00'),
  ('t3_38400', 'Last Argument of Pings', '2025-06-07', '2025-07-06', 16, 'Deutschland', 'Discordhausen', 12345, 'Discordstrasse 420', 'Last Argument of Pings Das erste TTS (Table Top Simulator) Turnier für Conquest auf dem deutschen Discordserver :) Hier der Link zum deutschen Discord: https://discord.gg/UBaAdJGe Bei Fragen gerne an Broschotto oder Redbeard wenden', 'https://www.tabletopturniere.de/t3_tournament.php?tid=38400', 'a0408267e182385af0a0b9181eb19a0917106b11e1758faaec310e58f60c2b88', 'ended', 5, 'ended', '2025-06-07 00:00:00'),
  ('t3_38289', 'Northern Bonelem Invitational Cup v2.0 - TBBGEP', '2025-08-08', '2025-08-10', 6, 'Deutschland', 'Ganderkesee', 27777, 'absolut geheim', 'Vor einigen Jahren wurden vier Männer und zwei Frauen einer Spezialeinheit wegen eines Verbrechens verurteilt, das sie nicht begangen hatten. Sie brachen aus dem Gefängnis aus und tauchten in Ganderkesee unter. Seit dem werden sie von der Militärpolizei g', 'https://www.tabletopturniere.de/t3_tournament.php?tid=38289', 'ceb82c58dfe096aa1bb7ae566dd2b947ec383f331698400661be97e069b3b900', 'ended', 5, 'ended', '2025-08-08 00:00:00'),
  ('t3_38842', 'Last Kings of Pirmasens', '2025-10-04', '2025-10-04', 10, 'Deutschland', 'Pirmasens', 66953, 'Adlerstr. 35', 'Hallo, wir heißen euch herzlich zu unserem ersten Conquest TLAoK Turnier in Pirmasens Willkomen! Gespielt wird nach den aktuellen Regeln. Armeegröße: 1500 Punkte Rundenzahl: 3', 'https://www.tabletopturniere.de/t3_tournament.php?tid=38842', '833221b693066a930c1ab5413c4ac3123d0b1765c29e60ddaa243b881c95c4d3', 'ended', 3, 'ended', '2025-10-04 00:00:00'),
  ('t3_39398', 'Last Argument of Pings - Teil 2', '2025-10-17', '2025-11-16', 16, 'Deutschland', 'Discordhausen', 80101, 'Discordhausen 1', 'Last Argument of Pings - Teil 2 Das TTS (Table Top Simulator) Turnier für Conquest auf dem deutschen Discordserver :) Hier der Link zum deutschen Discord: https://discord.gg/UBaAdJGe', 'https://www.tabletopturniere.de/t3_tournament.php?tid=39398', '8ea9359644e19ccef552aa40c035bc163561b5a58c7375a5e552bff456b364e7', 'ended', 5, 'ended', '2025-10-17 00:00:00');
