INSERT INTO `tournaments` (`id`,`name`,`date`,`end_date`,`max_players`,`country`,`city`,`zip`,`address`,`description`,`external_link`,`orga_id`,`state`,`current_round`,`current_round_state`,`created_at`) VALUES
  ('t3_34372', 'Victorum Liubice III: Drittes Lübecker Conquest Turnier', '2024-05-05', '2024-05-05', 16, 'Deutschland', 'Lübeck', 23554, 'Elmar-Limberg-Platz 6', 'Der Lübecker Brettspiel, Tabletop und PnP Verein Ludo Liubice veranstaltet sein drittes Conquest Turnier! Gespielt werden drei Runden mit 2000 Punkten. Die Szenarien und weitere Informationen findet ihr unter "Informationen und Regeln"', 'https://www.tabletopturniere.de/t3_tournament.php?tid=34372', 'd52ff7913e4a28a946266f3b65be373835e02177184b00f240665f0302ac7be1', 'ended', 3, 'ended', '2024-05-05 00:00:00'),
  ('t3_34373', 'Victorum Liubice IV: Viertes Lübecker Conquest Turnier', '2024-09-15', '2024-09-15', 20, 'Deutschland', 'Lübeck', 23554, 'Elmar-Limberg-Platz 6', 'Der Lübecker Brettspiel, Tabletop und PnP Verein Ludo Liubice veranstaltet sein viertes Conquest Turnier! Gespielt werden drei Runden mit 2000 Punkten. Die Szenarien und weitere Informationen findet ihr unter "Informationen und Regeln"', 'https://www.tabletopturniere.de/t3_tournament.php?tid=34373', 'd52ff7913e4a28a946266f3b65be373835e02177184b00f240665f0302ac7be1', 'ended', 3, 'ended', '2024-09-15 00:00:00'),
  ('t3_37154', 'Sidequest - Conquest im Sidequest #5', '2025-01-11', '2025-01-11', 16, 'Deutschland', 'Bremerhaven', 27568, 'Am Gitter 1', 'Wir freuen uns auf einen gemeinsamen Tag mit tollen Conquest-Partien mit euch! Neulinge wie Erfahrene sind Willkommen!', 'https://www.tabletopturniere.de/t3_tournament.php?tid=37154', 'dfb5fcc8c09328871c3694f29934b534f083ed8de129a6aafbeb7cd9ac4e69b5', 'ended', 3, 'ended', '2025-01-11 00:00:00'),
  ('t3_38014', 'Tag des Conquest', '2025-05-01', '2025-05-01', 12, 'Deutschland', 'München', 81379, 'Hofmannstraße 52', 'Hammer und Schild veranstaltet das erstes Conquest TlaoK Turnier in München. Startplätze: 12 Startgebühr: 15€ Termin: 01 Mai 2025 Veranstaltungsort: Hammer und Schild e.V. Dauer: 3 Runden zu je 2.5h Punkte: 2000 Punkte Armeen: Alle offiziell verfügbaren A', 'https://www.tabletopturniere.de/t3_tournament.php?tid=38014', '64ae95990f9bd99a631bf7839e2ded182da9b023c4b29fb054ed10e0367b0eed', 'ended', 3, 'ended', '2025-05-01 00:00:00'),
  ('t3_37715', 'Sidequest - Conquest im Sidequest #6', '2025-05-17', '2025-05-17', 16, 'Deutschland', 'Bremerhaven', 27580, 'Lange Straße 58', '2000 Punkte, 3 Spiele', 'https://www.tabletopturniere.de/t3_tournament.php?tid=37715', 'dfb5fcc8c09328871c3694f29934b534f083ed8de129a6aafbeb7cd9ac4e69b5', 'ended', 3, 'ended', '2025-05-17 00:00:00'),
  ('t3_37716', 'Sidequest - Conquest im Sidequest #7', '2025-07-19', '2025-07-19', 18, 'Deutschland', 'Bremerhaven', 27580, 'Lange Straße 58', '2000 Punkte, 3 Spiele', 'https://www.tabletopturniere.de/t3_tournament.php?tid=37716', 'dfb5fcc8c09328871c3694f29934b534f083ed8de129a6aafbeb7cd9ac4e69b5', 'ended', 3, 'ended', '2025-07-19 00:00:00'),
  ('t3_38386', 'Sidequest - Conquest im Sidequest #8', '2025-12-06', '2025-12-06', 18, 'Deutschland', 'Bremerhaven', 27580, 'Lange Straße 58', '2000 Punkte, 3 Spiele', 'https://www.tabletopturniere.de/t3_tournament.php?tid=38386', 'dfb5fcc8c09328871c3694f29934b534f083ed8de129a6aafbeb7cd9ac4e69b5', 'ended', 3, 'ended', '2025-12-06 00:00:00'),
  ('t3_40667', 'Sidequest - Conquest im Sidequest #9 -  Undying Loyalty', '2026-03-28', '2026-03-28', 18, 'Deutschland', 'Bremerhaven', 27580, 'Lange Straße 58', 'Da das Turnier an den Namelosentagen ausfällt, springen wir für unsere Freunde in Bremen ein und veranstalten das Nachfolgeturnier zum neunten Conquest-Turnier im Sidequest! 2000 Punkte, Spiel & Spaß bei drei Partien. Meldet euch an, das Event findet unab', 'https://www.tabletopturniere.de/t3_tournament.php?tid=40667', 'dfb5fcc8c09328871c3694f29934b534f083ed8de129a6aafbeb7cd9ac4e69b5', 'ended', 3, 'ended', '2026-03-28 00:00:00'),
  ('t3_39858', 'Sidequest - Conquest im Sidequest #10', '2026-06-06', '2026-06-06', 18, 'Deutschland', 'Bremerhaven', 27580, 'Lange Straße 58', '2000 Punkte, 3 Spiele', 'https://www.tabletopturniere.de/t3_tournament.php?tid=39858', 'dfb5fcc8c09328871c3694f29934b534f083ed8de129a6aafbeb7cd9ac4e69b5', 'ended', 3, 'ended', '2026-06-06 00:00:00');
